// Round-bottom flask support ring with three legs
// Units: mm. Print orientation: legs on bed (z = 0), ring on top.

$fn = 128;

// --- Ring ---
ring_od        = 90;   // ring outer diameter
ring_id        = 66;   // ring inner diameter
ring_thick     = 6;    // ring thickness (Z)
ring_top_z     = 60;   // z of ring top face
ring_bottom_z  = ring_top_z - ring_thick; // z of ring bottom face

// --- Legs ---
leg_d          = 6;    // leg diameter
leg_pcd        = 78;   // diameter of circle through leg axes
leg_count      = 3;    // number of legs
leg_start_ang  = 0;    // first leg on +X axis (deg)
leg_overlap    = 0.5;  // leg extends into ring for a solid union

eps            = 0.5;  // cutter overshoot for clean differences

union() {
    // Ring (annulus)
    translate([0, 0, ring_bottom_z])
        difference() {
            cylinder(d = ring_od, h = ring_thick);
            translate([0, 0, -eps])
                cylinder(d = ring_id, h = ring_thick + 2 * eps);
        }

    // Legs
    for (i = [0 : leg_count - 1]) {
        a = leg_start_ang + i * 360 / leg_count;
        translate([leg_pcd / 2 * cos(a), leg_pcd / 2 * sin(a), 0])
            cylinder(d = leg_d, h = ring_bottom_z + leg_overlap);
    }
}
```

