// Spacer for raising a circuit board with a sunk socket-head screw
// Prints standing on the bed, z = 0 to 12, centred on the origin

$fn = 96;

// ---- Dimensions (mm) ----
body_d      = 24;    // spacer outer diameter
body_h      = 12;    // spacer height
hole_d      = 3.4;   // through hole diameter (screw clearance)
cbore_d     = 6.5;   // counterbore diameter (socket head)
cbore_depth = 5;     // counterbore depth from top face (z = 7 to 12)
eps         = 0.5;   // cutter overshoot past faces

difference() {
    // Main body
    cylinder(d = body_d, h = body_h);

    // Through hole along the axis
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = body_h + 2 * eps);

    // Counterbore from the top face
    translate([0, 0, body_h - cbore_depth])
        cylinder(d = cbore_d, h = cbore_depth + eps);
}
