// Sliding mount with dovetail rail
// Print orientation: base plate flat on bed, rail pointing up (+Z)

$fn = 64;

// ---------- Base plate ----------
plate_len   = 60;   // X length of base plate
plate_wid   = 40;   // Y width of base plate
plate_thk   = 6;    // Z thickness of base plate (z = 0..6)

// ---------- Dovetail rail ----------
rail_len    = plate_len; // rail runs full plate length (X)
rail_w_bot  = 10;   // rail width where it meets plate (at z = plate_thk)
rail_w_top  = 14;   // rail width at top face
rail_top_z  = 12;   // Z height of rail top face
rail_h      = rail_top_z - plate_thk; // rail height (6 mm)
fuse        = 0.01; // small overlap into plate so solids fuse cleanly

// ---------- Model ----------
union() {
    // Base plate, centred in X and Y, sitting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail: trapezoid in YZ, extruded along X
    // rotate([90,0,90]) maps 2D x -> Y, 2D y -> Z, extrusion -> X
    rotate([90, 0, 90])
        linear_extrude(height = rail_len, center = true)
            polygon(points = [
                [-rail_w_bot/2, plate_thk - fuse], // bottom left
                [ rail_w_bot/2, plate_thk - fuse], // bottom right
                [ rail_w_top/2, rail_top_z],       // top right
                [-rail_w_top/2, rail_top_z]        // top left
            ]);
}
