// Weighted base for a lab stand rod
// Print orientation: disc flat on bed, boss pointing up (+Z)

// ---------- Parameters ----------
base_d      = 100;   // base disc diameter
base_h      = 10;    // base disc thickness (z = 0 to 10)
boss_d      = 20;    // boss diameter
boss_top_z  = 30;    // top of boss (boss runs z = 10 to 30)
rod_hole_d  = 8.5;   // rod hole diameter
floor_t     = 2;     // closed floor under rod hole (hole bottom at z = 2)
overcut     = 0.5;   // extension of cutters past faces
overlap     = 0.01;  // small overlap between unioned parts

$fn = 128;

// ---------- Model ----------
difference() {
    union() {
        // Base disc
        cylinder(d = base_d, h = base_h);
        // Coaxial boss
        translate([0, 0, base_h - overlap])
            cylinder(d = boss_d, h = boss_top_z - base_h + overlap);
    }
    // Blind rod hole from top of boss down to floor_t above the bed
    translate([0, 0, floor_t])
        cylinder(d = rod_hole_d, h = boss_top_z - floor_t + overcut);
}
