// Door wedge - right-angled wedge with vertical through-slot
// Print orientation: flat bottom on the bed (z = 0), sloped face up.
// Placed at the user-specified coordinates (x 0..120, y 0..40).

// ---------------- Parameters ----------------
wedge_length   = 120;   // X length of wedge base (mm)
wedge_width    = 40;    // Y width of wedge (mm)
wedge_height   = 25;    // Z height at the tall end, x = 0 (mm)

slot_width     = 6;     // slot size along Y (mm)
slot_length    = 30;    // slot size along X (mm)
slot_center_x  = 60;    // slot centre X (mm)
slot_center_y  = 20;    // slot centre Y (mm)

cut_extra      = 1;     // overshoot for cutting shapes (mm)

$fn = 64;

// ---------------- Model ----------------
difference() {
    // Wedge: right triangle in XZ, extruded along +Y from 0 to wedge_width
    translate([0, wedge_width, 0])
        rotate([90, 0, 0])
            linear_extrude(height = wedge_width)
                polygon(points = [
                    [0, 0],
                    [wedge_length, 0],
                    [0, wedge_height]
                ]);

    // Vertical through-slot
    translate([slot_center_x - slot_length / 2,
               slot_center_y - slot_width / 2,
               -cut_extra])
        cube([slot_length, slot_width, wedge_height + 2 * cut_extra]);
}
