// Set of 4 identical spacer washers, printed flat in a single row along X
// Units: mm

// ---- Parameters ----
washer_count = 4;      // number of washers
outer_d      = 30;     // washer outer diameter
hole_d       = 10.5;   // washer centre hole diameter
thickness    = 2;      // washer thickness (Z)
gap          = 8;      // clear gap between neighbouring washers (edge to edge)
cut_extra    = 0.5;    // overshoot of cutting shapes past faces
$fn          = 128;    // facet count for round features

// ---- Derived ----
pitch   = outer_d + gap;                    // centre-to-centre spacing
x_start = -(washer_count - 1) * pitch / 2;  // first washer centre, row centred on origin

// ---- Single washer ----
module washer() {
    difference() {
        cylinder(d = outer_d, h = thickness);
        translate([0, 0, -cut_extra])
            cylinder(d = hole_d, h = thickness + 2 * cut_extra);
    }
}

// ---- Row of washers ----
for (i = [0 : washer_count - 1])
    translate([x_start + i * pitch, 0, 0])
        washer();
