```openscad
// Glass stirring rod rest - block with 3 V-grooves across the top
// Units: mm. Print orientation: base on bed (z = 0), building up +Z.

$fn = 64;

// ---- Block dimensions ----
block_len    = 50;   // length along X
block_wid    = 30;   // width along Y
block_h      = 15;   // height along Z

// ---- Groove dimensions ----
groove_count = 3;    // number of V-grooves
groove_pitch = 15;   // centre-to-centre spacing along X
groove_top_w = 8;    // V width at the top surface
groove_depth = 4;    // V depth (90-degree V: depth = top width / 2)

// ---- Cutting overshoot ----
eps          = 0.5;  // extension past cut faces (avoids coplanar faces)

// 2D V profile in (X, Z) coordinates; sides kept at 45 degrees
// and extended eps above the top surface
module v_profile() {
    polygon(points = [
        [-(groove_top_w / 2 + eps), block_h + eps],
        [  groove_top_w / 2 + eps,  block_h + eps],
        [  0,                       block_h - groove_depth]
    ]);
}

// One groove running the full width along Y (plus overshoot)
module v_groove(x_pos) {
    translate([x_pos, 0, 0])
        rotate([90, 0, 0])
            linear_extrude(height = block_wid + 2 * eps, center = true)
                v_profile();
}

difference() {
    // Main block, centred in X and Y, sitting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_h]);

    // V-grooves, centred as a group along X
    for (i = [0 : groove_count - 1])
        v_groove((i - (groove_count - 1) / 2) * groove_pitch);
}
