// Captive hex-nut clamping block
// Print orientation: bottom face (with hex pocket) on the bed, z = 0

// ---- Block dimensions ----
block_x = 30;      // block length in X (mm)
block_y = 24;      // block width in Y (mm)
block_z = 15;      // block height in Z (mm)

// ---- Through hole ----
hole_d = 5.5;      // vertical through-hole diameter (mm)

// ---- Hex nut pocket ----
hex_af    = 8.2;   // hex pocket size across flats (mm)
hex_depth = 4.2;   // hex pocket depth from bottom face (mm)

// ---- Misc ----
eps = 0.5;         // overshoot for clean boolean cuts (mm)
$fn = 96;          // resolution for round features

// Circumradius of hexagon from across-flats dimension
hex_r = hex_af / (2 * cos(30));

difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_z]);

    // Vertical through hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = block_z + 2 * eps);

    // Hex nut pocket from the bottom face.
    // $fn = 6 puts vertices on the X axis, so two flats are parallel to X.
    translate([0, 0, -eps])
        cylinder(r = hex_r, h = hex_depth + eps, $fn = 6);
}
