// Split collet - slotted tube
// Units: mm

$fn = 128;

outer_d    = 30;    // tube outer diameter
bore_d     = 25;    // tube bore diameter
height     = 20;    // tube height (z = 0 to 20)

slot_count = 6;     // number of axial slots
slot_w     = 2;     // slot width
slot_z0    = 10;    // slots run from this height up to the top

eps        = 0.5;   // overcut for clean boolean faces

outer_r = outer_d / 2;
bore_r  = bore_d / 2;

difference() {
    // tube body
    cylinder(h = height, r = outer_r);

    // bore
    translate([0, 0, -eps])
        cylinder(h = height + 2 * eps, r = bore_r);

    // axial slots through the wall, first one centred on +X
    for (i = [0 : slot_count - 1])
        rotate([0, 0, i * 360 / slot_count])
            translate([bore_r - eps - 1, -slot_w / 2, slot_z0])
                cube([(outer_r - bore_r) + 2 * eps + 2,
                      slot_w,
                      height - slot_z0 + eps]);
}
```

