// Cross-shaped bottle stabiliser
// Flat plus-sign plate, printed flat on the bed

$fn = 64;

// --- Dimensions (mm) ---
plate_thick   = 3;     // plate thickness (Z)
arm_length    = 70;    // overall length of each bar (X and Y)
arm_width     = 10;    // width of each bar
hole_d        = 4.5;   // diameter of all through-holes
end_hole_off  = 30;    // distance from origin to arm-end hole centres
cut_extra     = 0.5;   // extra length for cutting shapes past faces

difference() {
    // Plus-sign plate
    union() {
        translate([-arm_length/2, -arm_width/2, 0])
            cube([arm_length, arm_width, plate_thick]);
        translate([-arm_width/2, -arm_length/2, 0])
            cube([arm_width, arm_length, plate_thick]);
    }

    // Centre hole
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = plate_thick + 2*cut_extra);

    // Four arm-end holes
    for (a = [0, 90, 180, 270])
        rotate([0, 0, a])
            translate([end_hole_off, 0, -cut_extra])
                cylinder(d = hole_d, h = plate_thick + 2*cut_extra);
}
