```openscad
// Keyhole wall plate - hangs on a screw head
// Print orientation: flat on the bed, z = 0 up to plate_t

$fn = 96;

// ---- Plate ----
plate_l   = 70;   // plate length (X)
plate_w   = 35;   // plate width (Y)
plate_t   = 3;    // plate thickness (Z)

// ---- Keyhole ----
head_d    = 10;   // round entry hole diameter (screw head passes through)
head_x    = 0;    // entry hole centre X
head_y    = 0;    // entry hole centre Y
slot_w    = 4;    // slot width (screw shank)
slot_end_x = 10;  // X of the rounded slot end centre

// ---- Cutting overlap ----
eps       = 0.5;  // extension past cut faces

module keyhole_2d() {
    union() {
        // round entry hole
        translate([head_x, head_y]) circle(d = head_d);
        // slot from hole centre to rounded end
        hull() {
            translate([head_x, head_y])     circle(d = slot_w);
            translate([slot_end_x, head_y]) circle(d = slot_w);
        }
    }
}

difference() {
    // plate, centred in X and Y, resting on z = 0
    translate([-plate_l / 2, -plate_w / 2, 0])
        cube([plate_l, plate_w, plate_t]);

    // keyhole through-cut
    translate([0, 0, -eps])
        linear_extrude(height = plate_t + 2 * eps)
            keyhole_2d();
}
