// Stepped riser - 3 equal solid steps climbing in +X
// Print orientation: base on bed (z = 0), steps climb upward toward +X

// ---- Dimensions (mm) ----
num_steps   = 3;    // number of steps
step_len    = 15;   // length of each step along X
step_rise   = 6;    // height increase per step (first step height = 6)
riser_depth = 40;   // extrusion depth along Y (y = 0 to y = 40)

total_len   = num_steps * step_len;   // 45 mm overall length in X
top_height  = num_steps * step_rise;  // 18 mm top step height

// ---- Model ----
// Each block starts at its step's X position and runs to the far end (x = 45),
// so the blocks overlap and union into one solid staircase down to the bed.
union() {
    for (i = [0 : num_steps - 1]) {
        translate([i * step_len, 0, 0])
            cube([total_len - i * step_len, riser_depth, (i + 1) * step_rise]);
    }
}
