// Display base with 45-degree chamfered top edges
// Print orientation: bottom face on build plate (z = 0)

$fn = 64;

base_x    = 100;  // overall length in X (mm)
base_y    = 50;   // overall width in Y (mm)
base_h    = 15;   // overall height in Z (mm)
chamfer   = 4;    // 45-degree chamfer width on top edges (mm)

side_h    = base_h - chamfer;     // height where vertical sides stop (11 mm)
top_x     = base_x - 2 * chamfer; // top face length (92 mm)
top_y     = base_y - 2 * chamfer; // top face width (42 mm)
thin      = 0.01;                 // thickness of top slab used for hull (mm)

hull() {
    // Lower block with full footprint and sharp bottom edges
    translate([-base_x / 2, -base_y / 2, 0])
        cube([base_x, base_y, side_h]);

    // Thin top slab at reduced size, so the hull forms the 45-degree chamfers
    translate([-top_x / 2, -top_y / 2, base_h - thin])
        cube([top_x, top_y, thin]);
}
