// Gas cylinder label tag
// Print orientation: flat on bed, centred on origin in X/Y

// ---- Dimensions (mm) ----
tag_length    = 50;    // overall length along X
tag_width     = 25;    // overall width along Y
tag_thickness = 3;     // plate thickness along Z
corner_r      = 5;     // corner radius (top view)

hole_d        = 6;     // cable-tie hole diameter
hole_x        = -19;   // hole centre X
hole_y        = 0;     // hole centre Y

cut_extra     = 0.5;   // overshoot for clean boolean cuts
$fn           = 96;    // curve resolution

// ---- Model ----
difference() {
    // Rounded-corner plate
    linear_extrude(height = tag_thickness)
        hull() {
            for (sx = [-1, 1], sy = [-1, 1])
                translate([sx * (tag_length / 2 - corner_r),
                           sy * (tag_width  / 2 - corner_r)])
                    circle(r = corner_r, $fn = $fn);
        }

    // Cable-tie through hole
    translate([hole_x, hole_y, -cut_extra])
        cylinder(d = hole_d, h = tag_thickness + 2 * cut_extra, $fn = $fn);
}
